using System;
using System.Collections.Generic;
public enum PassengerType { General, Drunk, Sleeping, Comfort, Hurried, RouteChecking, Errand, Luggage, MuddyLuggage, Food, PrecisionStop, Talkative }
public enum PassengerRepresentativeStatus { None, NotPresented, Pending, Accepted, Deferred, Succeeded, Neutral, Failed }
[Serializable] public sealed class PassengerDirtEvent { public string Id; public int Amount; }
// A trip owns this state. No score, fare, route or vehicle mutations occur here.
[Serializable] public sealed class PassengerBehaviorState {
 public int FollowupChoice=-1;
 public bool FollowupPending,SleepInterrupted;
 public int Version=1,Variant,Choice=-1,DialogueStage,LastManners=100;
 public string Identity;
 // Candidate identity seeds content; the committed trip identity scopes physical effects.
 public string EffectTripIdentity,RepresentativeResponse;
 public PassengerRepresentativeStatus RepresentativeStatus;
 public bool BindEffectTrip(string trip){if(string.IsNullOrEmpty(trip))throw new ArgumentException("Missing effect trip identity");if(!string.IsNullOrEmpty(EffectTripIdentity)){if(EffectTripIdentity!=trip)throw new ArgumentException("Cannot rebind passenger effects");return false;}EffectTripIdentity=trip;return true;}
 public bool SetRepresentativeContext(PassengerRepresentativeStatus status,string response){if(!Enum.IsDefined(typeof(PassengerRepresentativeStatus),status))throw new ArgumentException("Unknown representative status");response=response??"";if(response.Length>240)response=response.Substring(0,240);if(RepresentativeStatus==status&&RepresentativeResponse==response)return false;RepresentativeStatus=status;RepresentativeResponse=response;return true;}
 bool UsesRepresentative {get{return Type==PassengerType.Comfort||Type==PassengerType.Hurried||Type==PassengerType.RouteChecking||Type==PassengerType.Errand||Type==PassengerType.PrecisionStop;}}
 string RepresentativeTopic {get{return Type==PassengerType.Comfort?"승차감":Type==PassengerType.Hurried?(Variant==0?"도착 예상":"약속 시간"):Type==PassengerType.Errand?"경유":Type==PassengerType.PrecisionStop?"안전 하차":"경로";}}
 string RepresentativeReaction {get{string topic=RepresentativeTopic;switch(RepresentativeStatus){case PassengerRepresentativeStatus.Accepted:return topic+" 요청에 답해 주신 내용을 확인했어요. "+(RepresentativeResponse??"");case PassengerRepresentativeStatus.Deferred:return topic+" 요청은 안전상 보류했으니 원래 운행대로 갈게요.";case PassengerRepresentativeStatus.Succeeded:return topic+" 약속을 이행해 주셔서 고마워요.";case PassengerRepresentativeStatus.Failed:return topic+" 약속의 실제 운행 결과를 확인했어요. 다음에는 부탁드려요.";case PassengerRepresentativeStatus.Neutral:return topic+" 결과는 추가 평가 없이 확인했어요. "+(RepresentativeResponse??"");case PassengerRepresentativeStatus.Pending:return topic+"은 아직 답변 전이니 별도 약속으로 생각하지 않을게요.";default:return topic+" 요청을 따로 정하지 않고 기본 운행으로 도착할게요.";}}}

 public PassengerType Type;
 public bool Cancelled;
 public bool Quiet,Boarded,Arrived,Settled,Sleeping,SpillPlanned,ConsumptionOccurred,SpillOccurred,MudOccurred;
 public float Elapsed,MovingSeconds,PreparationRemaining,UnloadRemaining,ArrivalElapsed;
 static readonly string[] labels={"일반","취객","잠자는 승객","승차감 민감","재촉·불만","경로 확인","용무·경유","짐 많은 승객","흙 묻은 짐","음식·음료","정밀 하차","대화·반복 질문"};
 static readonly string[][] variants={new[]{"차분한 인사","풍경 감상","짧은 인사"},new[]{"말 많은 밤","미안한 손님","조용한 귀가"},new[]{"미리 부탁","대화하다 잠듦","얕은 잠","깊은 잠"},new[]{"출발부터 조심","회전이 걱정됨","나아지는 승차감"},new[]{"미리 ETA 확인","신호 대기 재촉","도착 직전 확인"},new[]{"큰길 궁금증","짧은 길 확인","익숙한 길 비교"},new[]{"미리 부탁","중간 용무 확인","복귀 확인"},new[]{"큰 가방","여러 상자","흔들리기 쉬운 짐"},new[]{"흙 묻은 가방","화분 운반","야외 작업 짐"},new[]{"간식","음료","도시락"},new[]{"입구 확인","보행 동선 확인","안전 지점 확인"},new[]{"고민 이야기","지역 질문","반복 질문"}};
 static readonly string[][] intros={new[]{"안녕하세요. 목적지까지 부탁해요.","창밖을 보며 갈게요.","반갑습니다. 출발할까요?"},new[]{"오늘 이야기가 자꾸 나오네요.","조금 취했네요. 폐를 끼치면 미안해요.","조용히 집까지 부탁해요."},new[]{"잠깐 눈 붙일게요. 도착하면 깨워 주세요.","오늘 하루가 길었어요… 졸리네요.","잠깐 잘게요. 중간에 위치를 물어볼 수도 있어요.","깊이 잠들면 도착해서 한 번 더 불러 주세요."},new[]{"부드럽게 운전해 주실 수 있나요?","차가 흔들리면 힘들어요.","편안하게 갈 수 있을까요?"},new[]{"도착 예상 시간을 알고 싶어요.","중간에 시간을 다시 확인할게요.","신호가 길어 보여도 안전하게 부탁해요."},new[]{"큰길로 가는 이유가 궁금해요.","짧은 길도 가능한가요?","제가 알던 길과 다른가 봐요."},new[]{"중간에 들를 곳을 먼저 확인하고 싶어요.","가능한 경유지가 있으면 알려 주세요.","용무 후 원래 목적지로 가는 거죠?"},new[]{"큰 가방을 싣고 내려야 해요.","상자를 여러 개 실어야 해요.","짐이 흔들리지 않게 싣고 싶어요."},new[]{"가방 밑에 흙이 묻었어요.","화분 받침에 흙이 남았네요.","밖에서 쓰던 짐이라 바닥이 더러워요."},new[]{"간식을 먹어도 될까요?","음료와 간식을 먹어도 될까요?","도시락을 먹어도 될까요?"},new[]{"입구 가까운 안전한 장소가 있나요?","내린 뒤 걸어갈 길을 확인하고 싶어요.","안전한 하차 지점인지 확인할게요."},new[]{"잠깐 제 이야기를 해도 될까요?","이 동네 이야기가 궁금해요.","앞서 물었던 걸 다시 확인해도 될까요?"}};
 public static PassengerBehaviorState Create(string identity,PassengerType type){if(string.IsNullOrEmpty(identity)||!Enum.IsDefined(typeof(PassengerType),type))throw new ArgumentException("Invalid passenger identity/type");int variant=(int)(DrunkRideState.Hash(identity+":variant")%(type==PassengerType.Sleeping?4u:3u));return new PassengerBehaviorState{Identity=identity,Type=type,Variant=variant,Quiet=type==PassengerType.Drunk&&variant==2,SpillPlanned=DrunkRideState.Hash(identity+":food-spill")%100<25};}
 public string TypeLabel {get{return labels[(int)Type];}}
 public string VariantLabel {get{return variants[(int)Type][Variant];}}
 public bool HasChoice {get{return Type!=PassengerType.General&&(Choice<0||FollowupPending)&&!Arrived&&!Settled&&!Sleeping;}}
 public bool BoardingReady {get{return !Settled&&PreparationRemaining<=0&&((Type!=PassengerType.Luggage&&Type!=PassengerType.MuddyLuggage)||Choice>=0);}}
 public bool UnloadReady {get{return UnloadRemaining<=0&&PreparationRemaining<=0;}}
 public float WorkRemaining {get{return PreparationRemaining+UnloadRemaining;}}
 public const int FoodPermissionSatisfaction=5;
 public int SatisfactionDelta {get{return Type==PassengerType.Food&&Boarded&&Choice==1?FoodPermissionSatisfaction:0;}}
 string[] ChoiceLabels {get{if(FollowupPending)return new[]{"남은 위치는 내비 안내로 확인해 주세요","운전에 집중하겠습니다. 편히 쉬세요"};switch(Type){case PassengerType.General:return new string[0];case PassengerType.Luggage:return new[]{"안전하게 짐을 싣고 내려드릴게요","이번에는 짐 적재가 어려워요"};case PassengerType.MuddyLuggage:return new[]{"보호 깔개를 준비할게요","그대로 실어드릴게요","이번에는 짐 적재가 어려워요"};case PassengerType.Food:return new[]{"밀봉해서 보관해 주세요","드셔도 괜찮아요","안전하게 정차한 동안 정리할게요"};default:return new[]{"짧게 확인하고 설명","운전에 집중하며 조용히 안내"};}}}
 public string[] ChoiceEffects {get{if(FollowupPending)return new[]{"만족도 변화 0 · 위치 안내 후 다시 수면","만족도 변화 0 · 다시 수면 · 후속 질문 줄임"};switch(Type){
  case PassengerType.General:return new string[0];
  case PassengerType.Luggage:return new[]{"만족도 변화 0 · 정차 적재 10초 / 하역 10초","만족도 변화 0 · 적재/하역 시간 0초"};
  case PassengerType.MuddyLuggage:return new[]{"만족도 변화 0 · 준비 10초 · 추가 청결도 감소 0","만족도 변화 0 · 하차 시 추가 청결도 -5","만족도 변화 0 · 추가 청결도 감소 0"};
  case PassengerType.Food:return new[]{"만족도 변화 0 · 추가 청결도 감소 0","만족도 +"+FoodPermissionSatisfaction+" · 실제 섭취 시 청결도 -2 · 흘림 확률 25%, 발생 시 추가 -6","만족도 변화 0 · 정차 정리 10초 · 추가 청결도 감소 0"};
  default:return new[]{"대화 자체 만족도 변화 0 · "+(Type==PassengerType.Drunk&&Variant==2?"후속 수다 줄임":Type==PassengerType.Sleeping?"수면 시 도착 안내":"후속 대화 유지"),"대화 자체 만족도 변화 0 · 후속 대화 줄임"};
 }}}
 public string[] Choices {get{var labels=ChoiceLabels;var effects=ChoiceEffects;for(int i=0;i<labels.Length;i++)labels[i]+="\n"+effects[i];return labels;}}
 public string SelectedEffect {get{return FollowupChoice>=0?"만족도 변화 0 · 다시 수면":Choice>=0?ChoiceEffects[Choice]:"";}}
 public string Dialogue {get{return UsesRepresentative&&DialogueStage>0&&RepresentativeStatus==PassengerRepresentativeStatus.Accepted&&!Quiet&&!Arrived&&!Settled?RepresentativeReaction+"\n"+DialogueBody:DialogueBody;}}
 string DialogueBody {get{if(Settled)return CompletionReaction;if(WorkRemaining>0)return (Type==PassengerType.Food?"정차한 동안 음식을 정리하고 있어요.":Arrived?"짐을 안전하게 내리고 있어요.":"안전하게 짐을 준비하고 있어요.")+" "+Math.Ceiling(WorkRemaining)+"초";if(Arrived)return Sleeping?"도착했어요. 안전하게 정차한 뒤 깨워 주세요.":"목적지에 도착했네요.";if(FollowupPending)return "잠깐 깨어났어요. 아직 멀었나요? 안전할 때 알려 주세요.";if(Sleeping)return Variant==2?(SleepInterrupted?"잠깐 깨어 안내를 들은 뒤 다시 눈을 감았습니다.":"얕은 잠에 들었습니다."):Variant==1?"대답이 느려지더니 잠들었습니다.":Variant==3?"깊이 잠들었습니다. 도착 안내를 기다립니다.":"부탁한 대로 조용히 쉬고 있습니다.";if(Choice<0)return intros[(int)Type][Variant];if(Type==PassengerType.Food)return SpillOccurred?"앗, 흘렸어요. 청결도 -2 · 흘림으로 추가 -6이 생겼습니다.":ConsumptionOccurred?"먹고 난 부스러기가 생겼어요. 청결도 -2.":Choice==0?"밀봉해서 보관할게요.":Choice==2?"정리를 마쳤어요. 먹지 않고 보관할게요.":"허락해 주셔서 고마워요. 이동 중 먹으면 오염이 생길 수 있어요.";if(Quiet)return "운전에 집중해 주세요. 더 묻지 않고 조용히 갈게요.";if(UsesRepresentative&&DialogueStage>0&&RepresentativeStatus!=PassengerRepresentativeStatus.Accepted)return RepresentativeReaction;if(DialogueStage==0)return "말씀 기억할게요. "+variants[(int)Type][Variant]+" 이야기는 안전하게 이어가요.";switch(Type){case PassengerType.Comfort:return LastManners>=90?(Variant==0?"출발부터 조심해 주셔서 편안해요.":Variant==1?"회전도 편안하게 느껴지네요.":"조용히 쉬면서 한결 나아졌어요."):(Variant==0?"흔들림이 아직 느껴져요. 필요한 제동은 이해해요.":Variant==1?"회전할 때 짐과 몸을 잡게 되네요. 안전 조작은 이해해요.":"조금 더 쉬고 싶어요. 안전하게 부탁해요.");case PassengerType.Luggage:return Choice!=0?"이번에는 짐을 싣지 않았으니 그대로 갈게요.":Variant==0?"가방 고정을 확인했어요. 고마워요.":Variant==1?"상자 정리가 끝난 걸 확인했어요.":LastManners>=90?"안쪽 물건도 흔들리지 않아 안심이 돼요.":"안쪽 물건을 다시 확인할게요. 안전하게 부탁해요.";case PassengerType.MuddyLuggage:return Choice==0?"준비한 깔개가 짐을 받쳐 주고 있어요.":Choice==1?"보호 없이 실은 짐은 내릴 때 바닥을 확인할게요.":"오염된 짐은 이번에 싣지 않았어요.";case PassengerType.Hurried:return Variant==0?"처음 안내한 시간을 기억하고 있어요.":Variant==1?"신호를 기다리는 이유는 이해했어요.":"목적지가 가까워졌네요. 안내한 시간을 기억해요.";case PassengerType.RouteChecking:return "아까 설명한 "+variants[(int)Type][Variant]+" 내용을 기억하고 있어요.";case PassengerType.Errand:return Variant==2?"용무 뒤 원래 목적지 안내를 확인할게요.":"가능하다고 확인한 경유 약정만 따라갈게요.";case PassengerType.Drunk:return Variant==0?"아까 들어 주셔서 고마워요. 그 이야기 말인데요…":Variant==1?"계속 배려해 주셔서 고마워요.":"조용히 데려다주셔서 고마워요.";case PassengerType.PrecisionStop:return "확인된 안전 장소만 이용한다는 설명을 기억해요.";case PassengerType.Talkative:return Variant==0?"아까 제 이야기를 들어 주셔서 마음이 놓여요.":Variant==1?"아까 이야기한 동네를 창밖으로 보고 있어요.":"아까 답해 주신 내용이 생각났어요. 고마워요.";default:return "아까 확인한 대로 안전하게 가고 있어요.";}}}
 public string CompletionReaction {get{if(UsesRepresentative)return RepresentativeReaction;if(Type==PassengerType.Food)return SpillOccurred?"흘려서 미안해요. 내려서 확인해 주세요.":ConsumptionOccurred?"먹고 난 자리를 확인해 주세요. 감사합니다.":"음식을 정리해 둬서 깨끗하게 내렸어요.";if(Type==PassengerType.Sleeping)return !Sleeping?"짧은 길이었네요. 감사합니다.":Variant==1?"제가 잠들었네요. 감사합니다.":Variant==3?"여러 번 불러 주셔서 죄송하고 고마워요.":Variant==2?(SleepInterrupted?"중간에 깨어났을 때 배려해 주셔서 고마워요.":"편하게 쉬었어요. 감사합니다."):"부탁한 대로 깨워 주셔서 잘 쉬었어요.";if(Type==PassengerType.MuddyLuggage)return MudOccurred?"짐 때문에 흙이 묻었네요. 죄송해요.":"짐을 확인해 주셔서 감사합니다.";if(Type==PassengerType.Luggage)return Choice==0?"짐까지 안전하게 내려 주셔서 고마워요.":"이번에는 짐 없이 잘 도착했어요.";return Quiet?"조용히 배려해 주셔서 감사합니다.":Choice>=0?VariantLabel+" 말씀을 기억해 주셔서 고마워요.":"안전하게 도착했네요. 감사합니다.";}}
 public bool Respond(int choice,bool safelyStopped){if(!safelyStopped||!HasChoice||choice<0||choice>=Choices.Length)return false;if(FollowupPending){FollowupChoice=choice;FollowupPending=false;Sleeping=true;Quiet=choice==1;return true;}Choice=choice;Quiet=(Type==PassengerType.Drunk&&Variant==2)||choice==1&&Type!=PassengerType.Food&&Type!=PassengerType.MuddyLuggage&&Type!=PassengerType.Luggage;if(Type==PassengerType.Luggage&&choice==0||Type==PassengerType.MuddyLuggage&&choice==0||Type==PassengerType.Food&&choice==2)PreparationRemaining=10;return true;}
 public bool Board(){if(Boarded||!BoardingReady)return false;Boarded=true;return true;}
 public bool Advance(float seconds,bool safelyStopped,bool moving,float progress,int manners,bool paused=false){if(paused||Settled||float.IsNaN(seconds)||float.IsInfinity(seconds)||seconds<=0)return false;bool changed=false;LastManners=Math.Max(0,Math.Min(100,manners));if(safelyStopped&&!moving){float before=WorkRemaining;if(PreparationRemaining>0)PreparationRemaining=Math.Max(0,PreparationRemaining-seconds);else if(Arrived)UnloadRemaining=Math.Max(0,UnloadRemaining-seconds);changed=before>0&&WorkRemaining==0;}if(!Boarded)return changed;Elapsed+=seconds;if(moving&&!Arrived)MovingSeconds+=seconds;if(Arrived)return changed;if(MovingSeconds>=(Variant==1?35:Variant==3?25:20)&&progress<.85f&&Type==PassengerType.Sleeping&&!Sleeping&&!SleepInterrupted){Sleeping=true;changed=true;}if(Type==PassengerType.Sleeping&&Variant==2&&Sleeping&&!SleepInterrupted&&Choice>=0&&!Quiet&&MovingSeconds>=40&&safelyStopped&&!moving&&progress<.85f){Sleeping=false;SleepInterrupted=true;FollowupPending=true;changed=true;}if(MovingSeconds>=30&&DialogueStage==0){DialogueStage=1;changed=true;}if(Type==PassengerType.Food&&Choice==1&&!ConsumptionOccurred&&MovingSeconds>=20&&progress>=.5f&&progress<.85f){ConsumptionOccurred=true;SpillOccurred=SpillPlanned;changed=true;}return changed;}
 public void SuppressFollowup(){if(FollowupPending){FollowupPending=false;Sleeping=true;}}
 public bool Arrive(){if(!Boarded||Arrived||Settled)return false;FollowupPending=false;Arrived=true;ArrivalElapsed=Elapsed;if(Type==PassengerType.Luggage&&Choice==0)UnloadRemaining=10;return true;}
 public bool Finish(bool safelyStopped){if(!safelyStopped||!Arrived||Settled||!UnloadReady)return false;Settled=true;if(Type==PassengerType.MuddyLuggage&&Choice==1)MudOccurred=true;return true;}
 public bool ExitCancelled(){if(!Boarded||Settled)return false;Cancelled=true;Settled=true;FollowupPending=false;PreparationRemaining=0;UnloadRemaining=0;if(Type==PassengerType.MuddyLuggage&&Choice==1)MudOccurred=true;return true;}
 public PassengerDirtEvent[] DirtEvents {get{var events=new List<PassengerDirtEvent>();if(ConsumptionOccurred)events.Add(new PassengerDirtEvent{Id=(string.IsNullOrEmpty(EffectTripIdentity)?Identity:EffectTripIdentity)+":crumbs",Amount=2});if(SpillOccurred)events.Add(new PassengerDirtEvent{Id=(string.IsNullOrEmpty(EffectTripIdentity)?Identity:EffectTripIdentity)+":spill",Amount=6});if(MudOccurred)events.Add(new PassengerDirtEvent{Id=(string.IsNullOrEmpty(EffectTripIdentity)?Identity:EffectTripIdentity)+":mud",Amount=5});return events.ToArray();}}
 public PassengerBehaviorState Copy(){return (PassengerBehaviorState)MemberwiseClone();}
 public void Validate(){if(!Enum.IsDefined(typeof(PassengerRepresentativeStatus),RepresentativeStatus)||RepresentativeResponse!=null&&RepresentativeResponse.Length>240)throw new ArgumentException("Invalid representative context");if(FollowupChoice< -1||FollowupChoice>1||FollowupPending&&(!SleepInterrupted||Sleeping||Arrived)||SleepInterrupted&&(Type!=PassengerType.Sleeping||Variant!=2)||Version!=1||string.IsNullOrEmpty(Identity)||!Enum.IsDefined(typeof(PassengerType),Type)||Variant<0||Variant>=(Type==PassengerType.Sleeping?4:3)||Choice< -1||Choice>=Choices.Length||DialogueStage<0||DialogueStage>1||LastManners<0||LastManners>100)throw new ArgumentException("Invalid passenger behavior");foreach(float value in new[]{Elapsed,MovingSeconds,PreparationRemaining,UnloadRemaining,ArrivalElapsed})if(float.IsNaN(value)||float.IsInfinity(value)||value<0)throw new ArgumentException("Invalid passenger timing");if(Settled&&WorkRemaining>0||PreparationRemaining>0&&!((Type==PassengerType.Luggage||Type==PassengerType.MuddyLuggage)&&Choice==0||Type==PassengerType.Food&&Choice==2)||PreparationRemaining>10||UnloadRemaining>10||MovingSeconds>Elapsed||ArrivalElapsed>Elapsed||Arrived&&!Boarded||Settled&&!Arrived&&!Cancelled||Cancelled&&(!Settled||!Boarded)||Sleeping&&(Type!=PassengerType.Sleeping||!Boarded)||ConsumptionOccurred&&(Type!=PassengerType.Food||Choice!=1||!Boarded)||SpillOccurred&&(!ConsumptionOccurred||!SpillPlanned)||MudOccurred&&(Type!=PassengerType.MuddyLuggage||Choice!=1||!Settled)||UnloadRemaining>0&&(!Arrived||Type!=PassengerType.Luggage||Choice!=0))throw new ArgumentException("Inconsistent passenger state");}
